const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('vi-VN').format(n)+' ₫',uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,6);
