let db;try{db=JSON.parse(localStorage.getItem('rikkei-db-v1'))||structuredClone(seed)}catch{db=structuredClone(seed)}let userId=sessionStorage.getItem('rikkei-user'),page='dashboard',calendarMonth=9,calendarYear=2026;const me=()=>db.members.find(m=>m.id===userId&&!m.locked),isAdmin=()=>me()?.role===roles[0],can=area=>isAdmin()||({events:[roles[1]],requests:[roles[1]],finance:[roles[4]],media:[roles[2]],logistics:[roles[3]],members:[]}[area]||[]).includes(me()?.role),save=()=>localStorage.setItem('rikkei-db-v1',JSON.stringify(db)),name=id=>db.members.find(m=>m.id===id)?.name||'Thành viên',eventName=id=>db.events.find(e=>e.id===id)?.title||'Hoạt động đã xóa',today=()=>new Date().toLocaleDateString('en-CA'),date=s=>new Date(s+'T12:00:00').toLocaleDateString('vi-VN'),initials=n=>n.split(' ').slice(-2).map(x=>x[0]).join(''),tag=s=>`<span class="badge ${/Chờ|Đang làm|Bản nháp|Tạm/.test(s)?'amber':/Từ chối|rời|Không/.test(s)?'red':/Chưa/.test(s)?'gray':''}">${esc(s)}</span>`;
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
const navItems=[['dashboard','◫','Tổng quan'],['members','♧','Thành viên'],['events','▦','Lịch & hoạt động'],['requests','▤','Đơn xin vắng'],['finance','◈','Quỹ & thu chi'],['media','▧','Truyền thông'],['logistics','☷','Hậu cần'],['notifications','♧','Thông báo'],['profile','◎','Hồ sơ cá nhân']];
function allowed(p){return ['dashboard','events','requests','finance','notifications','profile'].includes(p)||p==='members'&&can('members')||p==='media'&&can('media')||p==='logistics'&&can('logistics')}
function go(p){if(!allowed(p))return;page=p;render()}
function render(){if(!me())return login();if(!allowed(page))page='dashboard';const u=me();$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><div class="crest">R</div><div>RIKKEI FC<small>TOGETHER WE PLAY</small></div></div><div class="navlabel">KHÔNG GIAN CÂU LẠC BỘ</div><nav class="nav">${navItems.filter(x=>allowed(x[0])).map(([id,icon,label])=>`<button data-page="${id}" class="${page===id?'active':''}"><i>${icon}</i>${label}${id==='requests'&&can('requests')?`<span class="count">${db.requests.filter(r=>r.status==='Chờ duyệt').length}</span>`:''}</button>`).join('')}</nav><div class="sidefoot"><b>⚽ Một đội bóng. Một gia đình.</b><p class="muted">Tinh thần Rikkei, trên mọi sân cỏ.</p><button class="link" data-action="logout">⇥ Đăng xuất</button></div></aside><main class="main"><header class="topbar"><button class="mobiletoggle" data-action="menu" aria-label="Mở menu">☰</button><input id="globalSearch" placeholder="⌕  Tìm thành viên, hoạt động…" aria-label="Tìm kiếm"><div class="user"><button data-page="notifications" aria-label="Thông báo">♧ ${db.notifications.filter(n=>(n.member==='all'||n.member===u.id)&&!n.read.includes(u.id)).length}</button><span style="color:#e4e7ea">│</span><button class="avatar" data-page="profile">${initials(u.name)}</button><div class="userinfo"><b>${esc(u.name)}</b><div class="muted" style="font-size:10px;margin-top:5px">${esc(u.role)}</div></div></div></header><div class="content">${views[page]()}<div class="footnote">Bản dùng thử · Dữ liệu lưu trên trình duyệt này. Đăng nhập và phân quyền chỉ để mô phỏng; cần kết nối backend để sử dụng thực tế.</div></div></main>`;bind()}
function login(){userId=null;sessionStorage.removeItem('rikkei-user');$('#app').innerHTML=`<div class="login"><div class="loginart"><div class="brand" style="margin:0"><div class="crest">R</div><div>RIKKEI FC<small>TOGETHER WE PLAY</small></div></div><h1>Một đội bóng.<br>Một tinh thần.<br>Một gia đình.</h1><p style="color:#a7c1b2">Không gian kết nối và quản lý Câu lạc bộ Bóng đá Rikkei.<br>Cùng nhau ra sân, cùng nhau tiến bộ.</p></div><div class="loginform"><span class="badge red">CHÀO MỪNG TRỞ LẠI</span><h1 style="margin-top:20px">Đăng nhập câu lạc bộ</h1><p class="muted">Chọn tài khoản mẫu để trải nghiệm vai trò của bạn.</p><form id="loginForm"><div class="field"><label>Tài khoản dùng thử</label><select name="account">${db.members.filter(m=>!m.locked).map(m=>`<option value="${m.id}">${esc(m.name)} · ${esc(m.role)}</option>`).join('')}</select></div><div class="field"><label>Mật khẩu dùng thử</label><input name="password" type="password" required placeholder="Nhập rikkei123" autocomplete="current-password"></div><button class="btn primary">Đăng nhập →</button><p id="loginError" style="color:var(--red)" role="alert"></p></form><div class="demo"><b>Tài khoản demo cho 6 vai trò</b><br>Mật khẩu chung: <b>rikkei123</b><br>Bạn có thể đăng xuất và đổi vai trò để kiểm tra quy trình duyệt đơn. Không dùng mật khẩu cá nhân.</div></div></div>`;$('#loginForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('password')!=='rikkei123'){$('#loginError').textContent='Mật khẩu chưa đúng. Mật khẩu dùng thử là rikkei123.';return}userId=f.get('account');sessionStorage.setItem('rikkei-user',userId);page='dashboard';render();toast('Đăng nhập thành công')};}
function head(title,desc,action=''){return `<div class="head"><div><h1>${title}</h1><div class="muted">${desc}</div></div>${action}</div>`}const button=(label,act,arg='',primary=false)=>`<button class="btn ${primary?'primary':''}" data-action="${act}" data-id="${arg}">${label}</button>`;
function stats(){let tx=db.transactions.filter(t=>t.date.startsWith('2026-10')),income=tx.filter(t=>t.type==='Thu').reduce((s,t)=>s+t.amount,0),expense=tx.filter(t=>t.type==='Chi').reduce((s,t)=>s+t.amount,0),balance=5000000+db.transactions.reduce((s,t)=>s+(t.type==='Thu'?t.amount:-t.amount),0);return `<div class="stats">${[['♧','Thành viên hoạt động',db.members.filter(m=>m.status==='Đang hoạt động').length,'Đồng đội cùng ra sân'],['▦','Hoạt động sắp tới',db.events.filter(e=>e.date>=today()).length,'Trong lịch câu lạc bộ'],['◈','Số dư quỹ hiện tại',money(balance),'Thu tháng 10: '+money(income)],['▤','Đơn chờ duyệt',db.requests.filter(r=>r.status==='Chờ duyệt'&&(can('requests')||r.member===userId)).length,'Chi tháng 10: '+money(expense)]].map(([i,t,n,d])=>`<div class="stat"><span class="icon">${i}</span><div class="muted">${t}</div><div class="number" style="${String(n).length>10?'font-size:23px':''}">${n}</div><small class="green">${d}</small></div>`).join('')}</div>`}
function nextMatch(){const e=[...db.events].filter(e=>e.date>=today()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))[0];if(!e)return '<div class="empty">Chưa có lịch đá sắp tới.</div>';let yes=Object.values(e.rsvps).filter(x=>x==='Tham gia').length,no=Object.values(e.rsvps).filter(x=>x==='Không tham gia').length;return `<div class="hero"><span class="badge">● TRẬN ĐẤU SẮP TỚI</span><div class="teams">RIKKEI FC <span>VS</span> ${esc(e.opponent)}</div><div class="matchmeta"><span>▦ ${date(e.date)} · ${e.time}</span><span>⌖ ${esc(e.place)}</span></div></div><div class="matchbottom"><div><b>${yes} thành viên tham gia</b><p class="muted" style="font-size:11px;margin:6px 0">${no} không tham gia · ${db.requests.filter(r=>r.event===e.id&&r.status==='Đã duyệt').length} đơn vắng đã duyệt</p></div>${button('Xem chi tiết →','eventDetail',e.id)}</div><div class="progress"><div style="width:${Math.min(100,yes/db.members.length*100)}%"></div></div>`}
function chart(){let months=['05','06','07','08','09','10'];return `<div class="panelhead"><h2>Thu chi câu lạc bộ</h2><span class="muted" style="font-size:10px">6 tháng gần nhất</span></div><div class="bars">${months.map(m=>{let t=db.transactions.filter(t=>t.date.startsWith('2026-'+m)),a=t.filter(t=>t.type==='Thu').reduce((s,t)=>s+t.amount,0),b=t.filter(t=>t.type==='Chi').reduce((s,t)=>s+t.amount,0);return `<div class="barpair" title="Tháng ${m}: Thu ${money(a)}, Chi ${money(b)}"><i style="height:${Math.min(100,a/40000)}%"></i><i style="height:${Math.min(100,b/40000)}%"></i><small>Thg ${+m}</small></div>`}).join('')}</div><p class="muted" style="font-size:10px;text-align:center">● <span style="color:#d92b36">Thu</span>　● <span style="color:#e8a8ad">Chi</span>　· Chưa có giao dịch tháng 5–9</p>`}
function calendar(){const first=new Date(calendarYear,calendarMonth,1).getDay(),days=new Date(calendarYear,calendarMonth+1,0).getDate();return `<div class="panelhead"><h2>Tháng ${calendarMonth+1}, ${calendarYear}</h2><div><button data-action="monthPrev" aria-label="Tháng trước">‹</button>　<button data-action="monthNext" aria-label="Tháng sau">›</button></div></div><div class="calendar">${['CN','T2','T3','T4','T5','T6','T7'].map(d=>`<span class="muted">${d}</span>`).join('')}${'<span></span>'.repeat(first)}${Array.from({length:days},(_,i)=>{let d=`${calendarYear}-${String(calendarMonth+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`,e=db.events.find(e=>e.date===d);return `<button class="${d===today()?'today':e?'event':''}" data-action="calendarDay" data-id="${d}" title="${e?esc(e.title):date(d)}">${i+1}</button>`}).join('')}</div><p class="muted" style="font-size:10px">● <span style="color:var(--red)">Ngày có hoạt động</span>　● Hôm nay</p>`}
const views={dashboard:()=>head(`Xin chào, ${esc(me().name.split(' ').slice(-2).join(' '))}! 👋`,'Một ngày tuyệt vời để cùng đồng đội tiến về phía trước.',can('events')?button('＋ Tạo buổi đá','eventForm','',true):button('＋ Gửi đơn xin vắng','requestForm','',true))+stats()+`<div class="grid"><div><section class="panel"><div class="panelhead"><h2>Hẹn nhau trên sân cỏ</h2><button class="link" data-page="events">Tất cả hoạt động →</button></div>${nextMatch()}</section><section class="panel"><div class="panelhead"><h2>Thao tác nhanh</h2></div><div class="quick">${(isAdmin()?[['＋','Tạo buổi đá','eventForm'],['♧','Thêm thành viên','memberForm'],['↗','Ghi khoản thu','income'],['↘','Ghi khoản chi','expense']]:[['▦','Xem lịch đá','gotoEvents'],['▤','Gửi đơn xin vắng','requestForm'],['◎','Hồ sơ cá nhân','gotoProfile'],['♧','Xem thông báo','gotoNotifications']]).map(([i,t,a])=>`<button data-action="${a}"><b>${i}</b>${t}</button>`).join('')}</div></section><section class="panel">${chart()}</section></div><div><section class="panel">${calendar()}</section><section class="panel"><div class="panelhead"><h2>${can('requests')?'Đơn cần xử lý':'Đơn xin vắng của bạn'}</h2><button class="link" data-page="requests">Xem tất cả →</button></div>${requestRows(3)}</section><section class="panel"><div class="panelhead"><h2>${can('logistics')||isAdmin()?'Công việc hậu cần':'Bảng tin câu lạc bộ'}</h2></div>${can('logistics')||isAdmin()?taskRows(3):notificationRows(2)}</section></div></div>`,members:()=>head('Thành viên','Những đồng đội làm nên tinh thần Rikkei FC.',button('＋ Thêm thành viên','memberForm','',true))+`<section class="panel"><div class="filters"><input id="memberSearch" placeholder="Tìm tên, mã thành viên, email…"><select id="memberDept"><option value="">Tất cả các ban</option>${[...new Set(db.members.map(m=>m.department))].map(d=>`<option>${esc(d)}</option>`).join('')}</select><select id="memberRole"><option value="">Tất cả chức vụ</option>${roles.map(r=>`<option>${r}</option>`).join('')}</select><select id="memberStatus"><option value="">Tất cả trạng thái</option>${['Đang hoạt động','Tạm nghỉ','Đã rời CLB'].map(s=>`<option>${s}</option>`).join('')}</select>${button('↓ Xuất CSV','exportMembers')}</div><div class="tablewrap" id="memberTable">${memberTable(db.members)}</div></section>`,events:()=>head('Lịch & hoạt động','Ra sân đúng giờ. Thi đấu hết mình.',can('events')?button('＋ Tạo buổi đá','eventForm','',true):'')+`<div class="grid"><section class="panel"><div class="filters"><input id="eventSearch" placeholder="Tìm hoạt động, đối thủ, sân bóng…"><select id="eventPeriod"><option value="all">Tất cả hoạt động</option><option value="upcoming">Sắp tới</option><option value="past">Đã diễn ra</option></select></div><div id="eventList">${eventRows(db.events)}</div></section><section class="panel">${calendar()}</section></div>`,requests:()=>head('Đơn xin vắng',can('requests')?'Xem xét đơn và gửi phản hồi đến thành viên.':'Theo dõi đơn xin vắng và phản hồi của ban quản lý.',button('＋ Gửi đơn xin vắng','requestForm','',true))+`<section class="panel"><div class="filters"><select id="requestStatus"><option value="">Tất cả trạng thái</option>${['Chờ duyệt','Đã duyệt','Từ chối'].map(s=>`<option>${s}</option>`).join('')}</select></div><div id="requestList">${requestRows()}</div></section>`,finance:()=>head('Quỹ & thu chi','Minh bạch từng khoản đóng góp, vững vàng từng trận đấu.',can('finance')?`<div>${button('＋ Ghi khoản thu','income','',true)} ${button('− Ghi khoản chi','expense')}</div>`:'')+stats()+`<section class="panel"><div class="panelhead"><h2>${can('finance')?'Lịch sử giao dịch':'Giao dịch liên quan đến bạn'}</h2>${button('↓ Báo cáo CSV','exportFinance')}</div><div class="filters"><input id="txSearch" placeholder="Tìm nội dung giao dịch…"><select id="txType"><option value="">Thu & chi</option><option>Thu</option><option>Chi</option></select><select id="txCategory"><option value="">Tất cả danh mục</option>${categories.map(c=>`<option>${c}</option>`).join('')}</select><input id="txFrom" type="date" aria-label="Từ ngày"><input id="txTo" type="date" aria-label="Đến ngày"></div><div id="txTable" class="tablewrap">${txTable(financeTx())}</div><p id="txSummary" class="muted"></p></section><section class="panel">${chart()}</section>`,media:()=>head('Ban Truyền thông','Kể câu chuyện của đội bóng, lan tỏa tinh thần Rikkei.',button('＋ Tạo bài viết','postForm','',true))+`<section class="panel"><div class="filters"><input id="postSearch" placeholder="Tìm bài viết…"><select id="postStatus"><option value="">Tất cả trạng thái</option>${['Bản nháp','Chờ duyệt','Đã đăng'].map(s=>`<option>${s}</option>`).join('')}</select></div><div id="postList">${postRows(db.posts)}</div></section>`,logistics:()=>head('Ban Hậu cần','Chuẩn bị chu đáo, để đồng đội yên tâm thi đấu.',button('＋ Thêm công việc','taskForm','',true))+`<section class="panel"><div class="filters"><input id="taskSearch" placeholder="Tìm công việc, người phụ trách…"><select id="taskStatus"><option value="">Tất cả trạng thái</option>${['Chưa làm','Đang làm','Hoàn thành'].map(s=>`<option>${s}</option>`).join('')}</select></div><div id="taskList">${taskRows()}</div></section>`,notifications:()=>head('Trung tâm thông báo','Cập nhật từ câu lạc bộ và những thông tin dành cho bạn.',isAdmin()||can('events')||can('media')?button('＋ Tạo thông báo','notificationForm','',true):button('Đánh dấu đã đọc','readAll'))+`<section class="panel">${notificationRows()}</section>`,profile:()=>head('Hồ sơ cá nhân','Thông tin của bạn trong gia đình Rikkei FC.',button('Chỉnh sửa hồ sơ','profileForm','',true))+`<section class="panel"><div class="row"><span class="avatar" style="width:64px;height:64px;font-size:23px">${initials(me().name)}</span><div><h2>${esc(me().name)}</h2><p class="muted">${me().id} · ${esc(me().role)}</p>${tag(me().status)}</div></div><div class="formgrid">${[['Email',me().email],['Số điện thoại',me().phone],['Ban',me().department],['Khóa / Bộ phận',me().unit],['Ngày tham gia',date(me().joined)],['Trạng thái đóng quỹ',db.transactions.some(t=>t.member===userId&&t.category==='Phí thành viên'&&t.date.startsWith('2026-10'))?'Đã ghi nhận đóng quỹ tháng 10':'Chưa ghi nhận đóng quỹ tháng 10']].map(([k,v])=>`<div><p class="muted">${k}</p><b>${esc(v)}</b></div>`).join('')}</div></section><section class="panel"><h2>Lịch sử tham gia</h2>${db.events.filter(e=>e.rsvps[userId]||e.attendance[userId]).map(e=>`<div class="row"><div class="grow"><b>${esc(e.title)}</b><p>${date(e.date)}</p></div>${tag(e.attendance[userId]?'Đã điểm danh':e.rsvps[userId]||'Không tham gia')}</div>`).join('')||'<p class="muted">Bạn chưa xác nhận hoạt động nào.</p>'}</section>`};
const categories=['Phí thành viên','Đóng góp','Thuê sân','Nước uống','Dụng cụ','Giải đấu','Truyền thông','Khoản khác'];
function memberTable(ms){return `<table><thead><tr><th>THÀNH VIÊN</th><th>BAN / CHỨC VỤ</th><th>LIÊN HỆ</th><th>TRẠNG THÁI</th><th></th></tr></thead><tbody>${ms.map(m=>`<tr><td><div class="user"><span class="avatar">${initials(m.name)}</span><div><b>${esc(m.name)}</b><div class="muted" style="margin-top:5px;font-size:10px">${m.id}</div></div></div></td><td>${esc(m.role)}<div class="muted" style="font-size:10px;margin-top:5px">${esc(m.department)}</div></td><td>${esc(m.email)}<div class="muted" style="font-size:10px;margin-top:5px">${esc(m.phone)}</div></td><td>${tag(m.locked?'Tài khoản khóa':m.status)}</td><td><button class="link" data-action="memberForm" data-id="${m.id}">Chi tiết / Sửa</button></td></tr>`).join('')}</tbody></table>${ms.length?'':'<div class="empty">Không tìm thấy thành viên phù hợp.</div>'}`}
function eventRows(es){return [...es].sort((a,b)=>a.date.localeCompare(b.date)).map(e=>`<div class="row"><div style="background:#fff0f1;padding:12px;border-radius:8px;text-align:center;color:var(--red)"><b style="font-size:22px">${+e.date.slice(-2)}</b><div style="font-size:9px">THÁNG ${+e.date.slice(5,7)}</div></div><div class="grow"><b>${esc(e.title)}</b><p>${e.time} · ${esc(e.place)}</p>${e.result?tag(e.result):tag(e.rsvps[userId]||'Chưa xác nhận')}</div>${button('Chi tiết','eventDetail',e.id)}</div>`).join('')||'<div class="empty">Chưa có hoạt động phù hợp.</div>'}
function requestRows(limit,status=''){let rs=db.requests.filter(r=>(can('requests')||r.member===userId)&&(!status||r.status===status));if(limit)rs=rs.slice(0,limit);return rs.map(r=>`<div class="row"><span class="avatar">${initials(name(r.member))}</span><div class="grow"><b>${esc(name(r.member))}</b><p>${esc(eventName(r.event))} · ${date(r.date)}</p><p>${esc(r.reason)}</p>${r.reply?`<p><b>Phản hồi:</b> ${esc(r.reply)}</p>`:''}${tag(r.status)}</div><button class="link" data-action="requestDetail" data-id="${r.id}">${can('requests')&&r.status==='Chờ duyệt'?'Xử lý':'Chi tiết'}</button></div>`).join('')||'<div class="empty">Không có đơn xin vắng.</div>'}
function taskRows(limit,ts=db.tasks){return (limit?ts.slice(0,limit):ts).map(t=>`<div class="row"><span style="color:#35956c;font-size:19px">${t.status==='Hoàn thành'?'☑':'□'}</span><div class="grow"><b class="${t.status==='Hoàn thành'?'taskdone':''}">${esc(t.title)}</b><p>${esc(t.owner)} · Hạn ${date(t.deadline)}</p><p>${esc(eventName(t.event))}</p></div>${tag(t.status)}${can('logistics')?`<button class="link" data-action="taskForm" data-id="${t.id}">Sửa</button>`:''}</div>`).join('')||'<div class="empty">Không có công việc phù hợp.</div>'}
function notificationRows(limit){let ns=db.notifications.filter(n=>n.member==='all'||n.member===userId);return (limit?ns.slice(0,limit):ns).map(n=>`<div class="row"><span class="avatar">♧</span><div class="grow"><b>${esc(n.title)}</b><p>${esc(n.content)}</p><p>${date(n.date)}</p></div>${n.read.includes(userId)?tag('Đã đọc'):`<button class="link" data-action="read" data-id="${n.id}">Đánh dấu đã đọc</button>`}</div>`).join('')||'<div class="empty">Chưa có thông báo mới.</div>'}
const financeTx=()=>db.transactions.filter(t=>can('finance')||t.member===userId);
function txTable(ts){return `<table><thead><tr><th>NGÀY</th><th>NỘI DUNG</th><th>DANH MỤC</th><th>SỐ TIỀN</th><th>NGƯỜI GHI NHẬN</th><th></th></tr></thead><tbody>${ts.map(t=>`<tr><td>${date(t.date)}</td><td><b>${esc(t.content)}</b>${t.receipt?`<div><button class="link" data-action="receipt" data-id="${t.id}">Xem chứng từ</button></div>`:''}</td><td>${esc(t.category)}</td><td style="color:${t.type==='Thu'?'#32956b':'#d92b36'}">${t.type==='Thu'?'+':'−'}${money(t.amount)}</td><td>${esc(t.owner)}</td><td>${can('finance')?`<button class="link" data-action="txForm" data-id="${t.id}">Sửa</button>`:''}</td></tr>`).join('')}</tbody></table>${ts.length?'':'<div class="empty">Không có giao dịch phù hợp.</div>'}`}
function postRows(ps){return ps.map(p=>`<div class="row">${p.image?`<img src="${esc(p.image)}" style="width:75px;height:65px;object-fit:cover;border-radius:6px" alt="Ảnh bài viết">`:'<span class="avatar">▧</span>'}<div class="grow"><b>${esc(p.title)}</b><p>${esc(p.content)}</p><p>Lịch đăng: ${date(p.date)}</p></div>${tag(p.status)}<button class="link" data-action="postForm" data-id="${p.id}">Chỉnh sửa</button></div>`).join('')||'<div class="empty">Không có bài viết phù hợp.</div>'}
function modal(title,body){$('#modal').innerHTML=`<div class="dialoghead"><h2>${title}</h2><button data-action="close" aria-label="Đóng">✕</button></div>${body}`;if(!$('#modal').open)$('#modal').showModal();bind($('#modal'))}
const field=(label,key,value='',type='text',required=true)=>`<div class="field"><label for="f-${key}">${label}</label><input id="f-${key}" name="${key}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="1" step="1"':''}></div>`,select=(label,key,values,value)=>`<div class="field"><label for="f-${key}">${label}</label><select id="f-${key}" name="${key}">${values.map(v=>{let [a,b]=Array.isArray(v)?v:[v,v];return `<option value="${esc(a)}" ${a===value?'selected':''}>${esc(b)}</option>`}).join('')}</select></div>`,area=(label,key,value='',required=false)=>`<div class="field"><label for="f-${key}">${label}</label><textarea id="f-${key}" name="${key}" ${required?'required':''}>${esc(value)}</textarea></div>`,form=(body,extra='')=>`<form id="editForm">${body}<p id="formError" style="color:var(--red)" role="alert"></p><div class="actions">${extra}<button type="button" class="btn" data-action="close">Hủy</button><button class="btn primary">Lưu thông tin</button></div></form>`;
function handleForm(fn){$('#editForm').onsubmit=async e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));for(let input of e.target.querySelectorAll('[required]'))if(!String(data[input.name]||'').trim()){$('#formError').textContent='Vui lòng nhập đầy đủ các trường bắt buộc.';return}try{await fn(data,e.target);save();$('#modal').close();render();toast('Đã lưu thông tin thành công')}catch(err){$('#formError').textContent=err.message}}}
function memberForm(id,personal=false){if(!personal&&!can('members'))return;let m=db.members.find(m=>m.id===id)||{id:'RK'+uid(),name:'',email:'',phone:'',role:roles[5],department:'Đội bóng',status:'Đang hoạt động',joined:today(),unit:'',note:'',locked:false};modal(personal?'Chỉnh sửa hồ sơ':id?'Thông tin thành viên':'Thêm thành viên',form(`<div class="formgrid">${field('Họ tên','name',m.name)}${field('Email','email',m.email,'email')}${field('Số điện thoại','phone',m.phone,'tel')}${field('Khóa / Bộ phận','unit',m.unit)}</div>${personal?'':`<div class="formgrid">${select('Chức vụ','role',roles,m.role)}${field('Ban','department',m.department)}${select('Trạng thái','status',['Đang hoạt động','Tạm nghỉ','Đã rời CLB'],m.status)}${field('Ngày tham gia','joined',m.joined,'date')}</div>${area('Ghi chú nội bộ','note',m.note)}${select('Tài khoản','locked',[['false','Mở tài khoản'],['true','Khóa tài khoản']],String(m.locked))}`}`,id&&!personal?`<button type="button" class="btn" data-action="deleteMember" data-id="${id}">Xóa thành viên</button>`:''));handleForm(d=>{if(db.members.some(x=>x.id!==m.id&&x.email===d.email))throw Error('Email này đã được sử dụng.');if(!personal&&id===userId&&(d.locked==='true'||d.role!==roles[0]))throw Error('Không thể khóa hoặc hạ quyền tài khoản quản trị đang đăng nhập.');Object.assign(m,d,personal?{}:{locked:d.locked==='true'});if(!id)db.members.push(m)})}
function eventForm(id){if(!can('events'))return;let e=db.events.find(e=>e.id===id)||{id:uid(),title:'',opponent:'',date:today(),time:'18:30',place:'',owner:me().name,note:'',rsvps:{},attendance:{},result:''};modal(id?'Sửa lịch hoạt động':'Tạo buổi đá',form(`${field('Tên hoạt động','title',e.title)}<div class="formgrid">${field('Ngày','date',e.date,'date')}${field('Giờ','time',e.time,'time')}</div>${field('Đối thủ / Nội dung buổi tập','opponent',e.opponent)}${field('Địa điểm','place',e.place)}${field('Người phụ trách','owner',e.owner)}${area('Ghi chú','note',e.note)}`));handleForm(d=>{Object.assign(e,d);if(!id)db.events.push(e);notify(id?'Lịch hoạt động đã thay đổi':'Có lịch hoạt động mới',`${e.title} · ${date(e.date)} ${e.time} · ${e.place}`)})}
function eventDetail(id){let e=db.events.find(e=>e.id===id);if(!e)return;modal(esc(e.title),`<p class="muted">${date(e.date)} · ${e.time} · ${esc(e.place)}</p><p>Phụ trách: ${esc(e.owner)}</p><p>${esc(e.note)}</p>${e.result?`<p><b>Kết quả:</b> ${esc(e.result)}</p><p>Đội hình: ${esc(e.lineup||'')}</p><p>Ghi bàn: ${esc(e.scorers||'')}</p><p>${esc(e.afterNote||'')}</p>`:''}<div class="actions">${button('✓ Tham gia','rsvpYes',id,true)}${button('Không tham gia','rsvpNo',id)}${button('Xin vắng','requestForEvent',id)}</div><h3>Xác nhận & điểm danh</h3>${db.members.filter(m=>m.status==='Đang hoạt động').map(m=>`<div class="row"><div class="grow">${esc(m.name)}</div>${tag(e.rsvps[m.id]||'Chưa xác nhận')}${can('events')?`<label><input type="checkbox" data-attendance="${m.id}" data-event="${id}" ${e.attendance[m.id]?'checked':''}> Có mặt</label>`:e.attendance[m.id]?tag('Có mặt'):''}</div>`).join('')}${can('events')?`<div class="actions">${button('Sửa lịch','eventForm',id)}${button('Lưu kết quả','resultForm',id)}</div>`:''}`)}
function requestForm(id,eventId){let r=db.requests.find(r=>r.id===id);if(r&&(r.member!==userId||r.status!=='Chờ duyệt'))return;let events=db.events.filter(e=>e.date>=today()||e.id===r?.event);if(!events.length){toast('Chưa có hoạt động sắp tới để xin vắng.');return}modal(r?'Sửa đơn xin vắng':'Gửi đơn xin vắng',form(`${select('Buổi đá / Sự kiện','event',events.map(e=>[e.id,e.title+' · '+date(e.date)]),r?.event||eventId)}${area('Lý do xin vắng','reason',r?.reason||'',true)}${area('Ghi chú bổ sung','note',r?.note||'')}${field('Minh chứng (ảnh, tối đa 2 MB)','attachment','','file',false)}<p class="muted">Ngày gửi: ${date(today())}</p>`));$('#f-attachment').accept='image/*';handleForm(async(d,f)=>{if(db.requests.some(x=>x.id!==id&&x.member===userId&&x.event===d.event&&x.status!=='Từ chối'))throw Error('Bạn đã có đơn xin vắng cho hoạt động này.');let attachment=await readFile(f.attachment.files[0]);let value={event:d.event,reason:d.reason.trim(),note:d.note,date:today(),attachment:attachment||r?.attachment||''};if(r)Object.assign(r,value);else db.requests.unshift({id:uid(),member:userId,status:'Chờ duyệt',reply:'',history:[],...value})})}
function requestDetail(id){let r=db.requests.find(r=>r.id===id);if(!r||!can('requests')&&r.member!==userId)return;modal('Chi tiết đơn xin vắng',`<p><b>${esc(name(r.member))}</b> · ${esc(eventName(r.event))}</p><p>${esc(r.reason)}</p><p>${esc(r.note||'')}</p>${r.attachment?`<img src="${esc(r.attachment)}" alt="Minh chứng" style="max-width:100%;max-height:240px">`:''}${tag(r.status)}${r.reply?`<p>Phản hồi: ${esc(r.reply)}</p>`:''}${r.history.map(h=>`<p class="muted">${esc(h.date)} · ${esc(h.by)} · ${esc(h.status)}</p>`).join('')}${r.status==='Chờ duyệt'&&can('requests')?`${area('Lời nhắn phản hồi','reply')}<div class="actions">${button('Từ chối','rejectRequest',id)}${button('Duyệt đơn','approveRequest',id,true)}</div>`:r.status==='Chờ duyệt'&&r.member===userId?`<div class="actions">${button('Rút đơn','withdrawRequest',id)}${button('Sửa đơn','requestForm',id,true)}</div>`:''}`)}
async function readFile(file){if(!file)return '';if(file.size>2*1024*1024)throw Error('Vui lòng chọn ảnh dưới 2 MB.');if(!file.type.startsWith('image/'))throw Error('Vui lòng chọn tệp hình ảnh.');return new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Không đọc được tệp.'));r.readAsDataURL(file)})}
function txForm(id,type='Thu'){if(!can('finance'))return;let t=db.transactions.find(t=>t.id===id)||{id:uid(),type,amount:'',content:'',category:type==='Thu'?'Phí thành viên':'Thuê sân',date:today(),member:'',owner:me().name};modal(id?'Sửa giao dịch':'Ghi khoản '+type.toLowerCase(),form(`<div class="formgrid">${select('Loại giao dịch','type',['Thu','Chi'],t.type)}${field('Số tiền (₫)','amount',t.amount,'number')}${field('Ngày','date',t.date,'date')}${select('Danh mục','category',categories,t.category)}</div>${field('Nội dung','content',t.content)}${select('Thành viên liên quan','member',[['','Khoản chung của CLB'],...db.members.map(m=>[m.id,m.name])],t.member)}${field('Ảnh hóa đơn (tối đa 2 MB)','receipt','','file',false)}`,id?`<button type="button" class="btn" data-action="deleteTx" data-id="${id}">Xóa giao dịch</button>`:''));$('#f-receipt').accept='image/*';handleForm(async(d,f)=>{if(!Number.isFinite(+d.amount)||+d.amount<=0)throw Error('Số tiền phải lớn hơn 0.');let receipt=await readFile(f.receipt.files[0]);Object.assign(t,d,{amount:+d.amount,owner:me().name,receipt:receipt||t.receipt||''});if(!id)db.transactions.unshift(t)})}
function taskForm(id){if(!can('logistics'))return;let t=db.tasks.find(t=>t.id===id)||{id:uid(),title:'',event:db.events[0]?.id,owner:me().name,deadline:today(),status:'Chưa làm',note:''};modal(id?'Chỉnh sửa công việc':'Thêm công việc hậu cần',form(`${field('Tên công việc','title',t.title)}${select('Hoạt động','event',db.events.map(e=>[e.id,e.title]),t.event)}<div class="formgrid">${field('Người phụ trách','owner',t.owner)}${field('Hạn hoàn thành','deadline',t.deadline,'date')}</div>${select('Trạng thái','status',['Chưa làm','Đang làm','Hoàn thành'],t.status)}${area('Ghi chú (sân bóng, dụng cụ, phương tiện…)','note',t.note)}`));handleForm(d=>{Object.assign(t,d);if(!id)db.tasks.push(t)})}
function postForm(id){if(!can('media'))return;let p=db.posts.find(p=>p.id===id)||{id:uid(),title:'',content:'',date:today(),status:'Bản nháp',image:''};modal(id?'Chỉnh sửa bài viết':'Tạo bài viết',form(`${field('Tiêu đề','title',p.title)}${area('Nội dung','content',p.content,true)}<div class="formgrid">${field('Ngày đăng dự kiến','date',p.date,'date')}${select('Trạng thái','status',['Bản nháp','Chờ duyệt','Đã đăng'],p.status)}</div>${field('Hình ảnh (tối đa 2 MB)','image','','file',false)}`));$('#f-image').accept='image/*';handleForm(async(d,f)=>{let image=await readFile(f.image.files[0]),was=p.status;Object.assign(p,{title:d.title,content:d.content,date:d.date,status:d.status,image:image||p.image});if(!id)db.posts.unshift(p);if(p.status==='Đã đăng'&&was!=='Đã đăng')notify(p.title,p.content)})}
function notify(title,content,member='all'){db.notifications.unshift({id:uid(),title,content,member,date:today(),read:[]})}
function filteredMembers(){const val=id=>$('#'+id)?.value||'';return db.members.filter(m=>(m.name+m.id+m.email).toLowerCase().includes(val('memberSearch').toLowerCase())&&(!val('memberDept')||m.department===val('memberDept'))&&(!val('memberRole')||m.role===val('memberRole'))&&(!val('memberStatus')||m.status===val('memberStatus')))}
function filteredTx(){const val=id=>$('#'+id)?.value||'';return financeTx().filter(t=>t.content.toLowerCase().includes(val('txSearch').toLowerCase())&&(!val('txType')||t.type===val('txType'))&&(!val('txCategory')||t.category===val('txCategory'))&&(!val('txFrom')||t.date>=val('txFrom'))&&(!val('txTo')||t.date<=val('txTo')))}
function csv(filename,rows){const content='\ufeff'+rows.map(r=>r.map(c=>'"'+String(c??'').replace(/"/g,'""').replace(/^([=+@-])/,'\t$1')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'}));let a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã xuất báo cáo CSV')}
function bind(root=document){root.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b.dataset.id));root.querySelectorAll('[data-attendance]').forEach(b=>b.onchange=()=>{if(!can('events'))return;db.events.find(e=>e.id===b.dataset.event).attendance[b.dataset.attendance]=b.checked;save();toast('Đã cập nhật điểm danh')});const on=(id,fn)=>{let el=$('#'+id);if(el)el.oninput=fn};['memberSearch','memberDept','memberRole','memberStatus'].forEach(id=>on(id,()=>{$('#memberTable').innerHTML=memberTable(filteredMembers());bind($('#memberTable'))}));['eventSearch','eventPeriod'].forEach(id=>on(id,()=>{let q=$('#eventSearch').value.toLowerCase(),p=$('#eventPeriod').value;$('#eventList').innerHTML=eventRows(db.events.filter(e=>(e.title+e.place+e.opponent).toLowerCase().includes(q)&&(p==='all'||(p==='upcoming'?e.date>=today():e.date<today()))));bind($('#eventList'))}));on('requestStatus',()=>{$('#requestList').innerHTML=requestRows(null,$('#requestStatus').value);bind($('#requestList'))});['txSearch','txType','txCategory','txFrom','txTo'].forEach(id=>on(id,()=>{let ts=filteredTx();$('#txTable').innerHTML=txTable(ts);$('#txSummary').textContent=`${ts.length} giao dịch · Tổng thu: ${money(ts.filter(t=>t.type==='Thu').reduce((s,t)=>s+t.amount,0))} · Tổng chi: ${money(ts.filter(t=>t.type==='Chi').reduce((s,t)=>s+t.amount,0))}`;bind($('#txTable'))}));['taskSearch','taskStatus'].forEach(id=>on(id,()=>{$('#taskList').innerHTML=taskRows(null,db.tasks.filter(t=>(t.title+t.owner).toLowerCase().includes($('#taskSearch').value.toLowerCase())&&(!$('#taskStatus').value||t.status===$('#taskStatus').value)));bind($('#taskList'))}));['postSearch','postStatus'].forEach(id=>on(id,()=>{$('#postList').innerHTML=postRows(db.posts.filter(p=>p.title.toLowerCase().includes($('#postSearch').value.toLowerCase())&&(!$('#postStatus').value||p.status===$('#postStatus').value)));bind($('#postList'))}));if($('#globalSearch'))$('#globalSearch').onkeydown=e=>{if(e.key==='Enter'){let q=e.target.value.trim();if(!q)return;if(can('members')){go('members');$('#memberSearch').value=q;$('#memberSearch').dispatchEvent(new Event('input'))}else{go('events');$('#eventSearch').value=q;$('#eventSearch').dispatchEvent(new Event('input'))}}}}
function action(a,id){if(a==='close')return $('#modal').close();if(a==='menu')return $('.sidebar').classList.toggle('open');if(a==='logout')return login();if(a.startsWith('goto'))return go({gotoEvents:'events',gotoProfile:'profile',gotoNotifications:'notifications'}[a]);if(a==='memberForm')return memberForm(id);if(a==='profileForm')return memberForm(userId,true);if(a==='eventForm')return eventForm(id);if(a==='eventDetail')return eventDetail(id);if(a==='requestForm')return requestForm(id);if(a==='requestForEvent')return requestForm(null,id);if(a==='requestDetail')return requestDetail(id);if(a==='income'||a==='expense'||a==='txForm')return txForm(id,a==='expense'?'Chi':'Thu');if(a==='taskForm')return taskForm(id);if(a==='postForm')return postForm(id);
if(a==='rsvpYes'||a==='rsvpNo'){let e=db.events.find(e=>e.id===id);if(!e)return;e.rsvps[userId]=a==='rsvpYes'?'Tham gia':'Không tham gia';save();eventDetail(id);render();toast('Đã cập nhật xác nhận tham gia');return}
if(a==='approveRequest'||a==='rejectRequest'){if(!can('requests'))return;let r=db.requests.find(r=>r.id===id);if(!r||r.status!=='Chờ duyệt')return;let reply=$('#f-reply').value.trim();if(a==='rejectRequest'&&!reply){toast('Vui lòng nhập lý do từ chối.');return}r.status=a==='approveRequest'?'Đã duyệt':'Từ chối';r.reply=reply;r.history.push({date:new Date().toLocaleString('vi-VN'),by:me().name,status:r.status});if(r.status==='Đã duyệt')db.events.find(e=>e.id===r.event).rsvps[r.member]='Không tham gia';notify('Đơn xin vắng '+r.status.toLowerCase(),eventName(r.event)+(reply?' · '+reply:''),r.member);save();$('#modal').close();render();toast('Đã xử lý đơn và gửi thông báo');return}
if(a==='withdrawRequest'){let r=db.requests.find(r=>r.id===id);if(r.member!==userId||r.status!=='Chờ duyệt')return;if(!confirm('Bạn muốn rút đơn xin vắng này?'))return;db.requests=db.requests.filter(r=>r.id!==id);save();$('#modal').close();render();toast('Đã rút đơn');return}
if(a==='deleteMember'){if(!can('members'))return;if(id===userId)return toast('Không thể xóa tài khoản đang đăng nhập.');if(!confirm('Xóa thành viên khỏi danh sách? Lịch sử hoạt động vẫn được giữ.'))return;db.members=db.members.filter(m=>m.id!==id);save();$('#modal').close();render();toast('Đã xóa thành viên');return}
if(a==='deleteTx'){if(!can('finance')||!confirm('Xóa giao dịch này? Số dư quỹ sẽ được cập nhật.'))return;db.transactions=db.transactions.filter(t=>t.id!==id);save();$('#modal').close();render();toast('Đã xóa giao dịch');return}
if(a==='read'||a==='readAll'){db.notifications.filter(n=>(n.member==='all'||n.member===userId)&&(a==='readAll'||n.id===id)).forEach(n=>{if(!n.read.includes(userId))n.read.push(userId)});save();render();return}
if(a==='notificationForm'){if(!isAdmin()&&!can('events')&&!can('media'))return;modal('Tạo thông báo',form(`${field('Tiêu đề','title')}${area('Nội dung thông báo','content','',true)}${select('Người nhận','member',[['all','Toàn bộ câu lạc bộ'],...db.members.map(m=>[m.id,m.name])],'all')}`));handleForm(d=>notify(d.title,d.content,d.member));return}
if(a==='resultForm'){if(!can('events'))return;let e=db.events.find(e=>e.id===id);modal('Lưu kết quả trận đấu',form(`${field('Kết quả (ví dụ: 3 – 2)','result',e.result)}${area('Đội hình','lineup',e.lineup||'')}${area('Cầu thủ ghi bàn','scorers',e.scorers||'')}${area('Ghi chú sau trận','afterNote',e.afterNote||'')}`));handleForm(d=>Object.assign(e,d));return}
if(a==='monthPrev'||a==='monthNext'){calendarMonth+=a==='monthPrev'?-1:1;if(calendarMonth<0){calendarMonth=11;calendarYear--}if(calendarMonth>11){calendarMonth=0;calendarYear++}render();return}
if(a==='calendarDay'){let es=db.events.filter(e=>e.date===id);modal('Hoạt động ngày '+date(id),es.length?eventRows(es):'<div class="empty">Không có hoạt động trong ngày này.</div>');return}
if(a==='exportMembers'){if(can('members'))csv('rikkei-thanh-vien.csv',[['Mã','Họ tên','Email','Điện thoại','Ban','Chức vụ','Trạng thái'],...filteredMembers().map(m=>[m.id,m.name,m.email,m.phone,m.department,m.role,m.status])]);return}
if(a==='exportFinance'){csv('rikkei-thu-chi.csv',[['Ngày','Loại','Nội dung','Danh mục','Số tiền','Người thực hiện'],...filteredTx().map(t=>[t.date,t.type,t.content,t.category,t.amount,t.owner])]);return}
if(a==='receipt'){let t=financeTx().find(t=>t.id===id);if(t?.receipt)modal('Chứng từ giao dịch',`<img src="${esc(t.receipt)}" alt="Hóa đơn" style="width:100%">`);return}}
render();
